if(!globalThis.crypto)globalThis.crypto=webcrypto;
const HERE=dirname(fileURLToPath(import.meta.url));
const HELP='Bank accountant receiving\n\n'+
 'starforge bank-statements accountant inspect --archive /private/account.tar [--out /private/summary.json]\n'+
 'starforge bank-statements accountant compare --before /private/earlier.tar --after /private/later.tar [--out /private/comparison.json]\n'+
 'starforge bank-statements accountant create --directory /private/accountant-review --name "October close review" --archive /private/account.tar [--archive /private/later.tar]\n'+
 'starforge bank-statements accountant add --directory /private/accountant-review --archive /private/later.tar\n'+
 'starforge bank-statements accountant show --directory /private/accountant-review\n'+
 'starforge bank-statements accountant note --directory /private/accountant-review --archive SHA256 --kind TRANSACTION --id UUID --status QUESTION --note-file /private/note.txt --actor "Accountant name" --summary "Source question" --request UUID [--parent ORIGINAL_EDITION_UUID]\n'+
 'starforge bank-statements accountant export --directory /private/accountant-review --out /private/review.tar\n'+
 'starforge bank-statements accountant receive --bundle /private/review.tar --directory /private/new-review\n'+
 'starforge bank-statements accountant prepare --directory /private/accountant-review --out /private/new-handover\n'+
 'starforge bank-statements accountant working-inspect --bundle /private/working.tar\n'+
 'starforge bank-statements accountant working-receive --bundle /private/working.tar --directory /private/accountant-working\n'+
 'starforge bank-statements accountant working-export --directory /private/accountant-working --out /private/working.tar\n'+
 'starforge bank-statements accountant prepare-working --directory /private/accountant-working --out /private/new-working-handover\n'+
 'starforge bank-statements accountant serve [--port 8458]\n\n'+
