 'Amounts, documents and close editions come from the complete original Bank archives. Private review notes have their own history.\n';
function flags(args){const result={archive:[]};while(args.length){const key=args.shift();need(/^--[a-z-]+$/.test(key),'ARGUMENT','Use documented --option value arguments.');const value=args.shift();need(typeof value==='string'&&!value.startsWith('--'),'ARGUMENT','Supply a value for '+key+'.');if(key==='--archive')result.archive.push(value);else{need(!Object.hasOwn(result,key.slice(2)),'ARGUMENT','Use one value for '+key+'.');result[key.slice(2)]=value;}}return result;}
function absolute(value,label){need(typeof value==='string'&&isAbsolute(value)&&resolve(value)===value,'ABSOLUTE_PATH','Use an absolute normalized '+label+' path.');return value;}
async function checkedDirectory(path){const value=await lstat(path);need(value.isDirectory()&&!value.isSymbolicLink()&&await realpath(path)===path,'REAL_DIRECTORY','Use a real private directory with original parents.');return path;}
async function ensurePrivate(path){let created=false;try{await mkdir(path,{mode:0o700});created=true;}catch(e){if(e.code!=='EEXIST')throw e;}await checkedDirectory(path);if(created)await syncDirectory(dirname(path));return path;}
async function syncDirectory(path){const handle=await open(path,constants.O_RDONLY);try{await handle.sync();}finally{await handle.close();}}
async function sourceFile(path,max){absolute(path,'source');const handle=await open(path,constants.O_RDONLY|constants.O_NOFOLLOW);try{const before=await handle.stat();need(before.isFile()&&before.size<=max,'SOURCE_SIZE','Choose a complete regular source file within its receiving limit.');const value=await handle.readFile(),after=await handle.stat();need(before.ino===after.ino&&before.dev===after.dev&&before.size===after.size&&before.mtimeMs===after.mtimeMs&&value.length===after.size,'SOURCE_CHANGED','The source changed during receiving. Read the same complete file again.');return new Uint8Array(value);}finally{await handle.close();}}
async function existing(path){try{const stat=await lstat(path);need(stat.isFile()&&!stat.isSymbolicLink(),'OUTPUT_FILE','Use a regular retained output file.');return new Uint8Array(await readFile(path));}catch(e){if(e.code==='ENOENT')return null;throw e;}}
async function exactOutput(path,value){absolute(path,'output');await checkedDirectory(dirname(path));const old=await existing(path);if(old){need(await digest(old)===await digest(value),'OUTPUT_CHANGED','The selected output already holds different complete bytes. Keep it and choose a new destination.');return {path,bytes:value.length,sha256:await digest(value)};}
 const temp=path+'.partial-'+randomUUID(),handle=await open(temp,constants.O_WRONLY|constants.O_CREAT|constants.O_EXCL|constants.O_NOFOLLOW,0o600);try{await handle.writeFile(value);await handle.sync();}finally{await handle.close();}
 try{await link(temp,path);}catch(e){if(e.code!=='EEXIST')throw e;const raced=await existing(path);need(raced&&await digest(raced)===await digest(value),'OUTPUT_CHANGED','Another receiver published different bytes at the selected output.');}finally{await unlink(temp).catch(()=>{});}
 await syncDirectory(dirname(path));return {path,bytes:value.length,sha256:await digest(value)};}
async function replaceReview(root,review){const path=join(root,'review.json'),temp=path+'.partial-'+randomUUID(),value=json(review),handle=await open(temp,'wx',0o600);try{await handle.writeFile(value);await handle.sync();}finally{await handle.close();}await rename(temp,path);await syncDirectory(root);}
async function loadNative(root){await checkedDirectory(root);const review=JSON.parse(new TextDecoder().decode(await sourceFile(join(root,'review.json'),16_000_000))),archives=[];for(const item of review.archives)archives.push(await inspectBankClose(await sourceFile(join(root,'archives',item.archiveId+'.tar'),MAX_ARCHIVE_BYTES),{filename:item.filename}));await validateReview(review,archives);return {review,archives};}
async function saveNative(root,review,archives){await ensurePrivate(join(root,'archives'));await ensurePrivate(join(root,'editions'));for(const a of archives)await exactOutput(join(root,'archives',a.archiveId+'.tar'),a.raw);for(const edition of review.editions)await exactOutput(join(root,'editions',edition.id+'.json'),json(edition));await replaceReview(root,review);}
async function archive(path){return inspectBankClose(await sourceFile(absolute(path,'Bank archive'),MAX_ARCHIVE_BYTES),{filename:basename(path)});}
function samePrefix(a,b){return a.id===b.id&&a.editions.length<=b.editions.length&&a.editions.every((e,i)=>e.sha256===b.editions[i].sha256)&&a.archives.every(x=>b.archives.some(y=>JSON.stringify(x)===JSON.stringify(y)));}
async function writeResult(value,out){if(out)await exactOutput(absolute(out,'JSON output'),json(value));process.stdout.write(new TextDecoder().decode(json(value)));return value;}
const STATIC_FILES=SOURCE_NAMES;
async function installedSource(){return sourceEdition(Object.fromEntries(await Promise.all(SOURCE_NAMES.map(async name=>[name,await readFile(join(HERE,name),'utf8')]))));}
export async function standaloneReader(raw=null){return standaloneWorking(await installedSource(),raw);}
async function prepareWorking(target,incoming){
 const out=absolute(target,'working handover');await checkedDirectory(dirname(out));await ensurePrivate(out);
 const raw=incoming.raw,received=await receiveWorking(raw),source=await installedSource();
 const files=new Map([['working.tar',raw],['reader.html',new TextEncoder().encode(await standaloneWorking(source,raw))],['START_HERE.txt',new TextEncoder().encode('Bank accountant working review\n\nOpen reader.html directly. It carries all original closes, review editions, unfinished drafts and the selected view. No note is silently retained as a review edition. Download working.tar and reopen it in the installed Accountant receiving desk or use bank-accountant working-receive.\nIf storage is unavailable, keep the visible complete working download; draft fields are a separate rescue and do not replace the original financial archives.\nRead ACCOUNTANT_RECEIVING.md and personally view every outgoing attachment.\n')]]);
 for(const name of SOURCE_NAMES)files.set(name,new TextEncoder().encode(source.files.find(f=>f.path===name).content));
