}
async function originalWorking(root){const descriptor=JSON.parse(new TextDecoder().decode(await sourceFile(join(root,'working-current.json'),100000)));need(/^[a-f0-9]{64}$/.test(descriptor.sha256??''),'WORKING_IDENTITY','Keep the exact selected original working file.');const raw=await sourceFile(join(root,'working-files',descriptor.sha256+'.tar'),MAX_BUNDLE_BYTES),received=await receiveWorking(raw);need(received.sha256===descriptor.sha256&&received.bytes===descriptor.bytes,'WORKING_CHANGED','The original working file changed.');return {raw,received};}
export async function prepareHandover(root,target){const {review,archives}=await loadNative(root),source=await installedSource(),sha=await digest(json(source)),working=await makeWorking({id:review.id,createdAt:review.createdAt,updatedAt:review.editions.at(-1)?.createdAt??review.createdAt,review,archives,drafts:[],activeDraftId:null,view:{...defaultView(),selected:archives[0]?.archiveId??''},sources:[source],runningSourceSha256:sha});
