async function serve(port){need(Number.isInteger(port)&&port>=1024&&port<=65535,'PORT','Choose a local port from 1024 through 65535.');const routes=new Map([...STATIC_FILES,'working-source.json'].map(name=>['/'+name,name]));const server=createServer(async(req,res)=>{try{need(req.method==='GET'||req.method==='HEAD','METHOD','Use GET to open the local accountant reader.');const u=new URL(req.url,'http://127.0.0.1'),name=u.pathname==='/'?'index.html':routes.get(u.pathname);if(!name){res.writeHead(404);res.end();return;}const body=name==='working-source.json'?Buffer.from(json(await installedSource())):await readFile(join(HERE,name)),type=name.endsWith('.mjs')?'text/javascript; charset=utf-8':name.endsWith('.html')?'text/html; charset=utf-8':name.endsWith('.css')?'text/css; charset=utf-8':name.endsWith('.json')?'application/json; charset=utf-8':'text/plain; charset=utf-8';res.writeHead(200,{'Content-Type':type,'Content-Length':body.length,'X-Content-Type-Options':'nosniff','Cache-Control':'no-store'});res.end(req.method==='HEAD'?undefined:body);}catch(error){res.writeHead(400,{'Content-Type':'text/plain; charset=utf-8'});res.end(error.message);}});await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(port,'127.0.0.1',resolve);});process.stdout.write(JSON.stringify({url:'http://127.0.0.1:'+port+'/',privateReview:'browser IndexedDB'})+'\n');return {server,close:()=>new Promise((resolve,reject)=>server.close(e=>e?reject(e):resolve()))};}
async function lease(root,args){await checkedDirectory(dirname(root));await ensurePrivate(root);const path=join(root,'receiving.lock');const handle=await open(path,constants.O_RDWR|constants.O_CREAT|constants.O_NOFOLLOW,0o600);try{need((await handle.stat()).isFile(),'REVIEW_LEASE','Choose the original private review lock.');}finally{await handle.close();}
 return new Promise((resolve,reject)=>{const child=spawn('flock',['--no-fork','--exclusive','--nonblock','--conflict-exit-code','73',path,process.execPath,fileURLToPath(import.meta.url),...args],{stdio:'inherit',env:{...process.env,STARFORGE_ACCOUNTANT_HELD_DIRECTORY:root}});child.once('error',reject);child.once('exit',(code,signal)=>{if(code===0)resolve({completed:true});else reject(Object.assign(new Error(code===73?'The original private review is already being received or edited. Continue after its current process completes.':'The accountant command ended with '+(signal??code)+'.'),{code:code===73?'REVIEW_BUSY':'ACCOUNTANT_COMMAND_FAILED'}));});});}
export async function runAccountantReceivingCli(args=process.argv.slice(2)){
 const original=[...args],command=args.shift();if(!command||command==='help'||command==='--help'){process.stdout.write(HELP);return {help:true};}const opts=flags(args);
 need(['inspect','compare','create','add','show','note','export','receive','prepare','working-inspect','working-receive','working-export','prepare-working','serve'].includes(command),'COMMAND','Choose a documented accountant receiving command.');
 if(command==='serve')return serve(Number(opts.port??8458));
 if(command==='working-inspect'){const received=await receiveWorking(await sourceFile(absolute(opts.bundle,'working file'),MAX_BUNDLE_BYTES));return writeResult(workingSummary(received),opts.out);}
 if(command==='inspect'){need(opts.archive.length===1,'ARCHIVE_REQUIRED','Choose one original archive.');const a=await archive(opts.archive[0]);return writeResult({summary:a.summary,identity:a.identity,originalManifest:a.manifest,sourceFiles:a.sourceFiles,customers:a.customers.map(c=>({id:c.id,name:c.name,sha256:c.sha256,files:c.files.size}))},opts.out);}
 if(command==='compare'){const before=await archive(opts.before),after=await archive(opts.after);return writeResult(compareCloses(before,after),opts.out);}
