 await checkedDirectory(root);let result;
 if(command==='working-receive'){const raw=await sourceFile(absolute(opts.bundle,'working file'),MAX_BUNDLE_BYTES),received=await receiveWorking(raw);await ensurePrivate(join(root,'working-files'));await exactOutput(join(root,'working-files',received.sha256+'.tar'),raw);const pointer=json(workingSummary(received)),path=join(root,'working-current.json'),temp=path+'.partial-'+randomUUID();const handle=await open(temp,'wx',0o600);try{await handle.writeFile(pointer);await handle.sync();}finally{await handle.close();}await rename(temp,path);await syncDirectory(root);return writeResult({directory:root,...workingSummary(received)});}
