 if(command==='create'){need(opts.archive.length>0,'ARCHIVE_REQUIRED','Choose at least one original Bank close.');const retained=await existing(join(root,'create-intent.json'));const selection=[];for(const path of opts.archive){const a=await archive(path);if(!selection.some(x=>x.archiveId===a.archiveId))selection.push(a);}const selectionHash=await digest(json(selection.map(a=>a.archiveId).sort())),name=opts.name??'Accountant review';let intent=retained?JSON.parse(new TextDecoder().decode(retained)):null;if(intent)need(intent.name===name&&intent.selectionHash===selectionHash,'CREATE_CHANGED','Continue this original receiving selection or use a new private directory.');else{need(!await existing(join(root,'review.json')),'REVIEW_EXISTS','This private directory already holds another review.');intent={id:randomUUID(),name,createdAt:new Date().toISOString(),selectionHash};await exactOutput(join(root,'create-intent.json'),json(intent));}
  let review=newReview(intent);for(const a of selection)review=attachArchive(review,a);const prior=await existing(join(root,'review.json'));if(prior){const actual=await loadNative(root);need(samePrefix(review,actual.review),'CREATE_CHANGED','The retained review differs from this original create request.');result={directory:root,review:actual.review,alreadyReceived:true};}else{await saveNative(root,review,selection);result={directory:root,review};}
